<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class PetTask extends Model { protected $guarded=[]; protected $casts=["scheduled_at"=>"datetime","completed_at"=>"datetime"]; public function reservation(){return $this->belongsTo(Reservation::class);} public function hotel(){return $this->belongsTo(Hotel::class);} public function pet(){return $this->belongsTo(Pet::class);} public function assignee(){return $this->belongsTo(User::class,"assigned_to");} public function completer(){return $this->belongsTo(User::class,"completed_by");} public function isOverdue(): bool {return $this->status==="pending" && $this->scheduled_at->isPast();} }